fn check_case(label: text, paths: [text], names: [text], modules: Dict<text, HirModule>) -> i64:
    print("CASE " + label)
    var driver = ProbeDriver(ctx: ProbeContext(source_paths_owner: paths, source_module_names_owner: names, hir_modules: modules))
    if driver.capture("cold-hir-module-source-mismatch", "/frozen") != false:
        print("FAIL error path returned success")
        return 1
    print("CASE_DONE " + label)
    0

fn main() -> i64:
    val source_path: text = "/other/main.spl"
    val module_name: text = "pkg.main"
    val source_paths: [text] = [source_path]
    val module_names: [text] = [module_name]
    val empty_paths: [text] = []
    val empty_names: [text] = []
    val empty: Dict<text, HirModule> = {}
    if check_case("empty-map", source_paths, module_names, empty) != 0:
        return 1
    val unrelated: Dict<text, HirModule> = {"pkg.other": HirModule(path: "/other/unrelated.spl", name: "pkg.other")}
    if check_case("missing-name", source_paths, module_names, unrelated) != 0:
        return 1
    if check_case("empty-names", source_paths, empty_names, unrelated) != 0:
        return 1
    val present: Dict<text, HirModule> = {"pkg.other": HirModule(path: "/other/unrelated.spl", name: "pkg.other"), "pkg.main": HirModule(path: "/other/main.spl", name: "pkg.main")}
    if check_case("present-name", source_paths, module_names, present) != 0:
        return 1
    if check_case("empty-sources", empty_paths, module_names, present) != 0:
        return 1
    print("NATIVE_DIAGNOSTIC_CASES_COMPLETED 5")
    0
